def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]

    one_lines = set()
    segments = []

    # Connect each pair of 1s that share a diagonal.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2 - r1) == abs(c2 - c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                cells = []
                r, c = r1, c1
                while True:
                    cells.append((r, c))
                    one_lines.add((r, c))
                    if (r, c) == (r2, c2):
                        break
                    r += dr
                    c += dc
                segments.append((cells, dr, dc))

    six_lines = set()
    # A 6 on a 1 segment extends in the perpendicular diagonal direction.
    for cells, dr, dc in segments:
        cellset = set(cells)
        for r, c in sixes:
            if (r, c) in cellset:
                pdr, pdc = dr, -dc
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w:
                    six_lines.add((rr, cc))
                    rr -= pdr
                    cc -= pdc
                rr, cc = r + pdr, c + pdc
                while 0 <= rr < h and 0 <= cc < w:
                    six_lines.add((rr, cc))
                    rr += pdr
                    cc += pdc

    for r, c in one_lines:
        if grid[r][c] == background:
            out[r][c] = 1
    for r, c in six_lines:
        if grid[r][c] == background:
            out[r][c] = 6
    return out
